            m.SatellitePrn[i] = p[1 + (i * 1)];
        }
        for (var i = 0; i < 20; i++)
        {
            m.SatelliteUsed[i] = p[21 + (i * 1)];
        }
        for (var i = 0; i < 20; i++)
        {
            m.SatelliteElevation[i] = p[41 + (i * 1)];
        }
        for (var i = 0; i < 20; i++)
        {
            m.SatelliteAzimuth[i] = p[61 + (i * 1)];
        }
        for (var i = 0; i < 20; i++)
        {
            m.SatelliteSnr[i] = p[81 + (i * 1)];
        }
        return m;
    }
