    /// <summary>Battery mode. Default (0) is that battery mode reporting is not supported or battery is in normal-use mode. Enum: MAV_BATTERY_MODE.</summary>
    public byte Mode { get; set; }

    /// <summary>Fault/health indications. These should be set when charge_state is MAV_BATTERY_CHARGE_STATE_FAILED or MAV_BATTERY_CHARGE_STATE_UNHEALTHY (if not, fault reporting is not supported). Enum: MAV_BATTERY_FAULT.</summary>
    public uint FaultBitmask { get; set; }

    public int Serialize(Span<byte> b)
    {
        b.Slice(0, WireMaxLength).Clear();
        BinaryPrimitives.WriteInt32LittleEndian(b.Slice(0, 4), CurrentConsumed);
        BinaryPrimitives.WriteInt32LittleEndian(b.Slice(4, 4), EnergyConsumed);
        BinaryPrimitives.WriteInt16LittleEndian(b.Slice(8, 2), Temperature);
        for (var i = 0; i < 10 && i < Voltages.Length; i++)
        {
            BinaryPrimitives.WriteUInt16LittleEndian(b.Slice(10 + (i * 2), 2), Voltages[i]);
        }
        BinaryPrimitives.WriteInt16LittleEndian(b.Slice(30, 2), CurrentBattery);
        b[32] = Id;
        b[33] = BatteryFunction;
        b[34] = Type;
        b[35] = (byte)BatteryRemaining;
        BinaryPrimitives.WriteInt32LittleEndian(b.Slice(36, 4), TimeRemaining);
        b[40] = ChargeState;
        for (var i = 0; i < 4 && i < VoltagesExt.Length; i++)
        {
            BinaryPrimitives.WriteUInt16LittleEndian(b.Slice(41 + (i * 2), 2), VoltagesExt[i]);
        }
        b[49] = Mode;
        BinaryPrimitives.WriteUInt32LittleEndian(b.Slice(50, 4), FaultBitmask);
        return WireMaxLength;
    }

    public static BatteryStatusMessage Deserialize(ReadOnlySpan<byte> payload)
    {
        Span<byte> p = stackalloc byte[WireMaxLength];
        payload.Slice(0, Math.Min(payload.Length, WireMaxLength)).CopyTo(p);
        var m = new BatteryStatusMessage();
        m.CurrentConsumed = BinaryPrimitives.ReadInt32LittleEndian(p.Slice(0, 4));
        m.EnergyConsumed = BinaryPrimitives.ReadInt32LittleEndian(p.Slice(4, 4));
        m.Temperature = BinaryPrimitives.ReadInt16LittleEndian(p.Slice(8, 2));
        for (var i = 0; i < 10; i++)
        {
            m.Voltages[i] = BinaryPrimitives.ReadUInt16LittleEndian(p.Slice(10 + (i * 2), 2));
        }
        m.CurrentBattery = BinaryPrimitives.ReadInt16LittleEndian(p.Slice(30, 2));
        m.Id = p[32];
        m.BatteryFunction = p[33];
        m.Type = p[34];
        m.BatteryRemaining = (sbyte)p[35];
        m.TimeRemaining = BinaryPrimitives.ReadInt32LittleEndian(p.Slice(36, 4));
        m.ChargeState = p[40];
        for (var i = 0; i < 4; i++)
        {
            m.VoltagesExt[i] = BinaryPrimitives.ReadUInt16LittleEndian(p.Slice(41 + (i * 2), 2));
        }
        m.Mode = p[49];
        m.FaultBitmask = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(50, 4));
        return m;
    }
}

/// <summary>AUTOPILOT_VERSION (148). Version and capability of autopilot software. This should be emitted in response to a request with MAV_CMD_REQUEST_MESSAGE.</summary>
internal sealed class AutopilotVersionMessage : IMavlinkMessage
{
