    {
        b.Slice(0, WireMaxLength).Clear();
        BinaryPrimitives.WriteUInt64LittleEndian(b.Slice(0, 8), Capabilities);
        BinaryPrimitives.WriteUInt64LittleEndian(b.Slice(8, 8), Uid);
        BinaryPrimitives.WriteUInt32LittleEndian(b.Slice(16, 4), FlightSwVersion);
        BinaryPrimitives.WriteUInt32LittleEndian(b.Slice(20, 4), MiddlewareSwVersion);
        BinaryPrimitives.WriteUInt32LittleEndian(b.Slice(24, 4), OsSwVersion);
        BinaryPrimitives.WriteUInt32LittleEndian(b.Slice(28, 4), BoardVersion);
        BinaryPrimitives.WriteUInt16LittleEndian(b.Slice(32, 2), VendorId);
        BinaryPrimitives.WriteUInt16LittleEndian(b.Slice(34, 2), ProductId);
        for (var i = 0; i < 8 && i < FlightCustomVersion.Length; i++)
        {
            b[36 + (i * 1)] = FlightCustomVersion[i];
        }
        for (var i = 0; i < 8 && i < MiddlewareCustomVersion.Length; i++)
        {
            b[44 + (i * 1)] = MiddlewareCustomVersion[i];
        }
        for (var i = 0; i < 8 && i < OsCustomVersion.Length; i++)
        {
            b[52 + (i * 1)] = OsCustomVersion[i];
        }
        for (var i = 0; i < 18 && i < Uid2.Length; i++)
        {
            b[60 + (i * 1)] = Uid2[i];
        }
