        payload.Slice(0, Math.Min(payload.Length, WireMaxLength)).CopyTo(p);
        var m = new AutopilotVersionMessage();
        m.Capabilities = BinaryPrimitives.ReadUInt64LittleEndian(p.Slice(0, 8));
        m.Uid = BinaryPrimitives.ReadUInt64LittleEndian(p.Slice(8, 8));
        m.FlightSwVersion = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(16, 4));
        m.MiddlewareSwVersion = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(20, 4));
        m.OsSwVersion = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(24, 4));
        m.BoardVersion = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(28, 4));
        m.VendorId = BinaryPrimitives.ReadUInt16LittleEndian(p.Slice(32, 2));
        m.ProductId = BinaryPrimitives.ReadUInt16LittleEndian(p.Slice(34, 2));
        for (var i = 0; i < 8; i++)
        {
            m.FlightCustomVersion[i] = p[36 + (i * 1)];
        }
        for (var i = 0; i < 8; i++)
        {
            m.MiddlewareCustomVersion[i] = p[44 + (i * 1)];
        }
        for (var i = 0; i < 8; i++)
        {
            m.OsCustomVersion[i] = p[52 + (i * 1)];
        }
        for (var i = 0; i < 18; i++)
        {
            m.Uid2[i] = p[60 + (i * 1)];
        }
        return m;
    }
}

