/// <summary>GPS_RTCM_DATA (233). RTCM message for injecting into the onboard GPS (used for DGPS)</summary>
internal sealed class GpsRtcmDataMessage : IMavlinkMessage
{
    public const uint WireId = 233;
    public const byte WireCrcExtra = 35;
    public const int WireMinLength = 182;
    public const int WireMaxLength = 182;

    uint IMavlinkMessage.WireId => WireId;
    byte IMavlinkMessage.WireCrcExtra => WireCrcExtra;
    int IMavlinkMessage.WireMaxLength => WireMaxLength;

    /// <summary>LSB: 1 means message is fragmented, next 2 bits are the fragment ID, the remaining 5 bits are used for the sequence ID. Messages are only to be flushed to the GPS when the entire message has been reconstructed on the autopilot. The fragment ID specifies which order the fragments should be assembled into a buffer, while the sequence ID is used to detect a mismatch between different buffers. The buffer is considered fully reconstructed when either all 4 fragments are present, or all the fragments before the first fragment with a non full payload is received. This management is used to ensure that normal GPS operation doesn't corrupt RTCM data, and to recover from a unreliable transport delivery order.</summary>
    public byte Flags { get; set; }

    /// <summary>data length [[bytes]]</summary>
    public byte Len { get; set; }

    /// <summary>RTCM message (may be fragmented)</summary>
    public byte[] Data { get; set; } = new byte[180];

    public int Serialize(Span<byte> b)
    {
        b.Slice(0, WireMaxLength).Clear();
        b[0] = Flags;
        b[1] = Len;
        for (var i = 0; i < 180 && i < Data.Length; i++)
        {
            b[2 + (i * 1)] = Data[i];
        }
        return WireMaxLength;
    }

    public static GpsRtcmDataMessage Deserialize(ReadOnlySpan<byte> payload)
    {
        Span<byte> p = stackalloc byte[WireMaxLength];
        payload.Slice(0, Math.Min(payload.Length, WireMaxLength)).CopyTo(p);
        var m = new GpsRtcmDataMessage();
        m.Flags = p[0];
        m.Len = p[1];
        for (var i = 0; i < 180; i++)
        {
            m.Data[i] = p[2 + (i * 1)];
        }
        return m;
    }
}

