    public ushort Mcc { get; set; }

    /// <summary>Mobile network code. If unknown, set to UINT16_MAX</summary>
    public ushort Mnc { get; set; }

    /// <summary>Location area code. If unknown, set to 0</summary>
    public ushort Lac { get; set; }

    /// <summary>Cellular modem instance number. Indexed from 1.</summary>
    public byte Id { get; set; }

    /// <summary>Download rate. [[KiB/s]]</summary>
    public uint LinkTxRate { get; set; }

    /// <summary>Upload rate. [[KiB/s]]</summary>
