    public byte BandNumber { get; set; }

    /// <summary>LTE radio frequency. [[MHz]]</summary>
    public float BandFrequency { get; set; }

    /// <summary>The channel number (CN). Absolute radio-frequency (ARFCN) / E-UTRA (EARFCN) / UTRA (UARFCN) / New radio (NR_CH).</summary>
    public uint ChannelNumber { get; set; }

