        BinaryPrimitives.WriteUInt16LittleEndian(b.Slice(2, 2), Mnc);
        BinaryPrimitives.WriteUInt16LittleEndian(b.Slice(4, 2), Lac);
        b[6] = Status;
        b[7] = FailureReason;
        b[8] = Type;
        b[9] = Quality;
        b[10] = Id;
        BinaryPrimitives.WriteUInt32LittleEndian(b.Slice(11, 4), LinkTxRate);
        BinaryPrimitives.WriteUInt32LittleEndian(b.Slice(15, 4), LinkRxRate);
