        m.Mnc = BinaryPrimitives.ReadUInt16LittleEndian(p.Slice(2, 2));
        m.Lac = BinaryPrimitives.ReadUInt16LittleEndian(p.Slice(4, 2));
        m.Status = p[6];
        m.FailureReason = p[7];
        m.Type = p[8];
        m.Quality = p[9];
        m.Id = p[10];
        m.LinkTxRate = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(11, 4));
        m.LinkRxRate = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(15, 4));
        m.CellTowerId = MavlinkText.Read(p.Slice(19, 9));
        m.BandNumber = p[28];
        m.BandFrequency = BinaryPrimitives.ReadSingleLittleEndian(p.Slice(29, 4));
        m.ChannelNumber = BinaryPrimitives.ReadUInt32LittleEndian(p.Slice(33, 4));
        m.RxLevel = BinaryPrimitives.ReadSingleLittleEndian(p.Slice(37, 4));
        m.TxLevel = BinaryPrimitives.ReadSingleLittleEndian(p.Slice(41, 4));
        m.RxQuality = BinaryPrimitives.ReadSingleLittleEndian(p.Slice(45, 4));
        m.Sinr = BinaryPrimitives.ReadSingleLittleEndian(p.Slice(49, 4));
        return m;
    }
}

